// In free mode, use the API

// Process numeric input for user display, just like in guided mode
let displayContent = userMessage.content;

// If input is a number, try to convert it to the corresponding time or date
const numericInput = userMessage.content.trim().match(/^(\d+)$/);
if (numericInput) {
  const optionIndex = parseInt(numericInput[1], 10) - 1;

  // Check if this might be a time selection
  if (availableTimes.length > 0) {
    const availableTimeSlots = availableTimes.map(time => time.formatted);
    if (optionIndex >= 0 && optionIndex < availableTimeSlots.length) {
      displayContent = availableTimeSlots[optionIndex];
      console.log(`[Free mode] Converted time option ${optionIndex + 1} to: ${displayContent}`);
    } else {
      // Try direct number matching for cases like "135" for option 135
      const directNumber = parseInt(userMessage.content.trim(), 10);
      if (!isNaN(directNumber) && directNumber > 0 && directNumber <= availableTimeSlots.length) {
        displayContent = availableTimeSlots[directNumber - 1];
        console.log(`[Free mode] Converted direct time number ${directNumber} to: ${displayContent}`);
      }
    }
  }

  // Check if this might be a date selection
  if (availableDates.length > 0) {
    const availableDateOptions = availableDates.map(date => date.display);
    if (optionIndex >= 0 && optionIndex < availableDateOptions.length) {
      displayContent = availableDateOptions[optionIndex];
      console.log(`[Free mode] Converted date option ${optionIndex + 1} to: ${displayContent}`);
    } else {
      // Try direct number matching for cases like "12" for option 12
      const directNumber = parseInt(userMessage.content.trim(), 10);
      if (!isNaN(directNumber) && directNumber > 0 && directNumber <= availableDateOptions.length) {
        displayContent = availableDateOptions[directNumber - 1];
        console.log(`[Free mode] Converted direct date number ${directNumber} to: ${displayContent}`);
      }
    }
  }
}

// Use the display content instead of the raw input if it was converted
const displayUserMessage = { ...userMessage, content: displayContent };
const updatedMessages = [...messages, displayUserMessage];

setMessages(updatedMessages);
setInput('');
setLoading(true);

