 16	  shop_id: string;
 17	  accountType: AccountType;
 18	  workers: Worker[];           // empty → individual account auto‑fills later
 19	  config: any;                 // raw tenant config blob (needed for greetings etc.)
 20	
 21	  // mutable session state -----------------------------------------------
 22	  step: number;                // 0‑6 as in the original Chatbox
 23	  clientName?: string;
 24	  selectedService?: string;
 25	  selectedWorker?: Worker;
 26	  selectedDate?: string;       // YYYY‑MM‑DD
 27	  selectedTime?: string;       // HH:MM
 28	}
 29	
 30	export interface FSMResult {
 31	  reply: string;               // text to send back to the user
 32	  context: BookingContext;     // mutated copy (immutability for safety)
 33	  appointment?: {              // present only when user confirmed (step 6 → "sim")
 34	    worker_id: string | number;
 35	    date: string;
 36	    start_time: string;
 37	    client_name: string;
 38	  };
 39	}
 40	
 41	// Common barber services (could be overridden per‑tenant via config later)
 42	const DEFAULT_SERVICES = [
 43	  'Corte de cabelo',
 44	  'Barba',
 45	  'Corte e barba',
 46	  'Sobrancelha',
 47	  'Hidratação',
 48	];
 49	
 50	// Helper ----------------------------------------------------------------
 51	function clone<T>(obj: T): T {
 52	  return JSON.parse(JSON.stringify(obj));
 53	}
 54	
 55	// Main reducer -----------------------------------------------------------
