// Helper function to format date options as a numbered list message
const formatDateOptionsMessage = () => {
  // Check if dates are available
  if (!availableDates || !Array.isArray(availableDates) || availableDates.length === 0) {
    console.log(" Warning: No available dates available when formatting message! Generating now.");
    generateDateOptions();
    return 'Gerando datas disponíveis...';
  }

  // *** MATCHING WHATSAPP BEHAVIOR ***
  // Since WhatsApp expects YYYY-MM-DD format for dates, we'll change the instruction
  // to match that behavior and avoid confusion
  const header = 'Escolha uma data digitando diretamente no formato AAAA-MM-DD:';

  // Still show options as a reference, but with clearer instruction
  const options = availableDates.map((date, index) => {
    // Add YYYY-MM-DD format alongside display format
    const yyyymmdd = formatDateToYMD(date.display);
    return `${index + 1}. ${date.display} (${yyyymmdd})`;
  }).join('\n');

  const note = 'IMPORTANTE: Digite a data no formato AAAA-MM-DD (exemplo: 2025-05-15)';

  return `${header}\n\n${options}\n\n${note}`;
};

// Helper to convert display date to YYYY-MM-DD
const formatDateToYMD = (displayStr) => {
  const match = displayStr.match(/(\d{2})\/(\d{2})/);
  if (match) {
    const day = match[1];
    const month = match[2];
    const year = new Date().getFullYear();
    return `${year}-${month}-${day}`;
  }
  return displayStr;
};

