    }

    // Add the time with its number
    timesToShow.push(`${i + 1}. ${timeStr}`);
  }

  const options = timesToShow.join('\n');
  const note = 'IMPORTANTE: Digite o horário no formato HH:MM (exemplo: 14:30)';

  return `${header}\n\n${options}\n\n${note}`;
};

