    } else if (dayOfWeek === 6) { // Saturday
      // If no valid Saturday hours format, use default
      businessHours = (config?.business?.saturdayHours && config.business.saturdayHours.includes('-')) 
        ? config.business.saturdayHours 
        : '08:00-14:00';
