                  content: question + "\n\n" + updatedTimeOptions
                };

                setMessages(prev => [...prev, timeInfoMessage]);
              });
          }

          setInput('');
          return;
        }

        // Handle confirmation step yes/no
        else if (ctx.step === 6 && num <= 2) {
          setInput('');
          if (num === 1) {
            // User selected "Sim" (1)
            sendMessage("sim");
          } else {
            // User selected "Não" (2)
            sendMessage("não");
          }
