            // Fallback if we don't have worker or date information
            const timeInfoMessage = {
              role: 'assistant',
              content: question + "\n\n" + timeOptions
            };
            setMessages(prev => [...prev, timeInfoMessage]);
          }
          setInput('');
          return;
        }
      }

      // Handle time selection by number - COMPLETELY FIXED APPROACH
      if (numMatch) {
        const num = parseInt(numMatch[0], 10);
        if (ctx.step === 5 && availableTimes.length >= num && num > 0) {
          // CRITICAL: First capture all the current state values before any updates
          // This prevents race conditions and ensures we use the correct values
          const currentState = { 
            selectedService: ctx.selectedService,
