          // First show the raw user input in the chat
          setMessages(prev => [...prev, { role: 'user', content: textToSend }]);

          // Clear input field
          setInput('');

          // CRITICAL FIX: Create a copy of the entire current ctx
          const updatedCtx = {...ctx};

          // Set the selected time and step while KEEPING all other fields
