      console.log(`🔍 - Worker: ${currentWorker?.name}`);
      console.log(`🔍 - Service: ${currentService}`);

      // CRITICAL FIX: Create a complete state object instead of using functional update
      // This ensures we set all fields explicitly and don't rely on the previous state
      const updatedState = {
        ...bookingState,
        selectedTime: time,
