      if (context.step === 2) {
        // Show service options as a message after a small delay
        setTimeout(() => {
          const serviceListMsg = formatServiceOptionsMessage();
          if (serviceListMsg) {
            setMessages(prev => [...prev, { role: 'assistant', content: serviceListMsg }]);
