                  color: msg.role === 'user' ? 'white' : 'text.primary',
                  p: 1.5,
                  borderRadius: msg.role === 'user' 
                    ? '18px 18px 4px 18px'
                    : '18px 18px 18px 4px',
                  maxWidth: '85%',
                  boxShadow: 1,
                  wordBreak: 'break-word',
                  whiteSpace: 'pre-wrap'
                }}
              >
                {msg.content}
              </Box>
              <Typography 
                variant="caption" 
                color="text.secondary"
                sx={{ mt: 0.5, mx: 1 }}
              >
                {msg.role === 'user' ? 'Você' : (config?.assistant?.name || 'Amanda')} • {new Date().toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
              </Typography>
            </Box>
          ))}
          <div ref={messagesEndRef} />
        </Box>

        {/* No UI elements - all options are shown as messages */}

      </Box>

      {/* Input Area */}
      <Box 
        sx={{ 
          display: 'flex', 
          gap: 1,
          p: 1,
          bgcolor: 'white',
          borderRadius: '0 0 8px 8px',
          boxShadow: 1
        }}
      >
        <TextField
          fullWidth
          placeholder={loading ? "Processando resposta..." : "Digite sua mensagem..."}
          value={input}
          onChange={e => setInput(e.target.value)}
          onKeyPress={handleKeyPress}
          disabled={loading}
          size="small"
          variant="outlined"
          InputProps={{
            sx: {
              borderRadius: 5,
              bgcolor: '#f9f9f9'
            }
          }}
          inputProps={{
            'aria-label': 'chat message input'
          }}
          sx={{ flex: 1 }}
        />
        <Button 
          onClick={() => sendMessage()} 
          disabled={loading} 
          variant="contained"
          aria-label="send message"
          sx={{
            borderRadius: '50%',
            minWidth: '40px',
            width: '40px',
            height: '40px',
            p: 0
          }}
        >
          {loading ? 
            <Box 
              sx={{ 
                width: 24, 
                height: 24, 
