        } else if (ctx.step === 5) {
          // Handle invalid time selection - show available times again
          // Add user's message
          setMessages(prev => [...prev, { role: 'user', content: textToSend }]);

          // IMPORTANT: Save the current date and worker to local variables first
          const currentDate = ctx.selectedDate;
          const currentWorker = ctx.selectedWorker;

          console.log(`🔍 Invalid time selection. Current state in ctx:`)
          console.log(`🔍 - Date: ${currentDate}`);
          console.log(`🔍 - Worker: ${currentWorker?.name}`);

          // Get the selected date display for context using our saved currentDate
          const displayDate = currentDate ? new Date(currentDate).toLocaleDateString('pt-BR', { 
            weekday: 'short', 
            day: '2-digit', 
            month: '2-digit' 
          }) : '';

          console.log(`🔍 Formatted display date: ${displayDate}`);

          // Show the available times again for the current date
