      // But use processedText for backend processing
      console.log(`📝 [Final] Input: "${textToSend}" → Display: "${displayText}" → Process: "${processedText}"`);

      setMessages(prev => [
        ...prev,
        { role: 'user', content: displayText }, // Show the converted value to the user
