  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1) !important;
}

.service-icon {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
  color: #0099FF;
}

.service-title {
  text-align: center;
  margin-bottom: 16px;
  font-weight: 600;
  color: #333;
}

.service-description {
  text-align: center;
  color: #666;
  margin-bottom: 20px;
}

.service-details {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
}

.service-time {
  display: flex;
  align-items: center;
  gap: 8px;
  color: #777;
}

.service-price {
  font-weight: 700;
  color: #0099FF;
}

.service-cta {
  border-radius: 30px !important;
}

/* Testimonials Section */
.testimonials-section {
  padding: 80px 0;
  background-color: #ffffff;
}

.testimonial-item {
  padding: 32px 24px;
  height: 100%;
  border-radius: 12px !important;
  transition: all 0.3s ease;
}

.testimonial-item:hover {
  transform: translateY(-5px);
  box-shadow: 0 8px 25px rgba(0, 0, 0, 0.1) !important;
}

.testimonial-rating {
  margin-bottom: 16px;
  display: flex;
  gap: 4px;
}

.testimonial-comment {
  font-style: italic;
  margin-bottom: 16px;
  color: #555;
  line-height: 1.6;
}

.testimonial-name {
  font-weight: 600;
  text-align: right;
  color: #333;
}

/* CTA Section */
.cta-section {
  padding: 80px 0;
  background-color: #f8f9fa;
}

.cta-paper {
  padding: 48px;
  border-radius: 12px !important;
  background: linear-gradient(135deg, #0099FF 0%, #0077CC 100%) !important;
  color: white;
}

.cta-title {
  margin-bottom: 16px;
  font-weight: 700;
}

.cta-description {
  margin-bottom: 24px;
  font-size: 1.1rem;
  opacity: 0.9;
}

/* Current Time Display */
.current-time-display {
  background-color: #f0f0f0;
  padding: 8px 0;
  border-top: 1px solid #e0e0e0;
  color: #777;
}

/* Calendar Customizations */
.fc .fc-toolbar-title {
  font-size: 1.2rem !important;
  font-weight: 600 !important;
  color: #333;
}

.fc .fc-button-primary {
  background-color: #0099FF !important;
  border-color: #0099FF !important;
}

.fc .fc-button-primary:hover {
  background-color: #0077CC !important;
  border-color: #0077CC !important;
}

.fc .fc-daygrid-day.fc-day-today {
  background-color: rgba(0, 153, 255, 0.1) !important;
}

.fc .fc-col-header-cell {
  background-color: #f5f5f5;
  font-weight: 600;
}

/* Responsive Adjustments */
@media (max-width: 960px) {
  .hero-section {
    padding: 60px 0;
  }

  .hero-content {
    min-height: auto;
  }

  .hero-title {
    font-size: 2.5rem;
  }

  .calendar-preview {
    margin-top: 40px;
  }

  .cta-paper {
    padding: 32px;
  }
}

@media (max-width: 600px) {
  .hero-title {
    font-size: 2rem;
  }

  .feature-item, .service-card, .testimonial-item {
    margin-bottom: 16px;
  }

  .cta-paper {
    padding: 24px;
  }

  .section-title {
    font-size: 1.8rem;
  }
}

