478	      );
479	    } catch (error) {
480	      console.error('Error during sign out:', error);
481	      // Fallback to landing page redirect
482	      window.location.href = '/';
483	    }
484	  };
485	
486	  /**
487	   * Get current user role from state or session storage
488	   * @returns {string|null} The user role
489	   */
490	  const getUserRole = () => {
491	    if (userRole) return userRole;
492	    
493	    try {
494	      return sessionStorage.getItem('userRole') || null;
495	    } catch (error) {
496	      console.error('Error getting user role from session storage:', error);
497	      return null;
498	    }
499	  };
