503	   * Performs optimistic local update and then syncs with server
504	   * @param {Object} newConfig - The new configuration
505	   */
506	  const updateConfig = async (newConfig) => {
507	    if (!newConfig) {
508	      console.error('Invalid config provided to updateConfig');
