525	      console.error('Error in updateConfig:', error);
526	      // Note: We don't rollback local state as it's an optimistic update
527	    }
528	  };
529	
530	  /**
531	   * Reset configuration to default based on user role
532	   * Updates both local state and server
533	   */
534	  const resetConfig = async () => {
