                  </Typography>
                  <Typography variant="subtitle1" className="testimonial-name">
                    - {review.name}
                  </Typography>
                </Paper>
              </Grid>
            ))}
          </Grid>
        </Container>
      </Box>

      {/* CTA Section */}
      <Box className="cta-section">
        <Container maxWidth="md">
          <Paper elevation={3} className="cta-paper">
            <Typography variant="h4" align="center" className="cta-title">
              Pronto para agendar seu horário?
            </Typography>
            <Typography variant="body1" align="center" className="cta-description">
              Comece agora e escolha o melhor horário disponível para você.
            </Typography>
            <Box textAlign="center" mt={3}>
              <Button 
                variant="contained" 
                color="primary" 
                size="large"
                component={Link}
                to="/admin"
                startIcon={<EventAvailableIcon />}
                className="main-cta-button"
              >
                Comece Agora
              </Button>
            </Box>
          </Paper>
        </Container>
      </Box>

      {/* Current date and time display */}
      <Box className="current-time-display">
        <Container maxWidth="lg">
          <Typography variant="body2" align="center">
            {currentDate.toLocaleDateString('pt-BR', { 
              weekday: 'long', 
              year: 'numeric', 
              month: 'long', 
              day: 'numeric' 
            })} | {currentDate.toLocaleTimeString('pt-BR', { 
              hour: '2-digit', 
              minute: '2-digit' 
            })}
          </Typography>
        </Container>
      </Box>

      {/* Aisol Footer */}
      <Box className="footer-section">
        <Container maxWidth="lg">
          <Box className="footer-content">
            <Typography variant="h6" className="footer-logo">
              Powered by <span className="aisol-brand">AISOL</span>
            </Typography>
            <Typography variant="body2" className="footer-copyright">
              © {new Date().getFullYear()} AISOL - Soluções em Inteligência Artificial. Todos os direitos reservados.
            </Typography>
            <Typography variant="body2" className="footer-tagline">
              Transformando negócios com tecnologia inteligente
            </Typography>
          </Box>
        </Container>
      </Box>
    </Box>
  );
};

export default LandingPage;

