import React, { useEffect } from "react";
import { BrowserRouter, Routes, Route } from "react-router-dom";
import { jwtDecode } from "jwt-decode";

import { ConfigProvider } from "./context/ConfigContext";
import { NotificationProvider } from "./components/ui/NotificationContext";

import LandingPage     from "./pages/LandingPage";     // ← new landing page
import AdminPage       from "./pages/AdminPage";        // ← example
import BookingWidget   from "./pages/BookingWidget";    // ← new share-link page

function AppInitializer({ children }) {
  useEffect(() => {
    // grab Cognito implicit-grant tokens from the URL fragment
    const hash = window.location.hash;
    if (hash) {
      const params = new URLSearchParams(hash.slice(1));

      // Check for access_token from Cognito response (implicit flow)
      const accessToken = params.get("access_token");
      const idToken = params.get("id_token");

      // Use either token for auth, with preference for id_token if available
      const token = idToken || accessToken;

      if (token) {
        try {
          // Decode the token to get user info
          const payload = jwtDecode(token);
          const accountType = payload['custom:accountType'] || 'individual';
          const username = payload['cognito:username'] || payload['sub'];

          // Save user information to session storage
          sessionStorage.setItem('idToken', token);
          sessionStorage.setItem('shopId', username);
          sessionStorage.setItem('userRole', accountType);

          // Always redirect to admin page after successful auth
          window.location.href = "/admin";
        } catch (error) {
          console.error('Error processing token:', error);
          sessionStorage.setItem('idToken', token); // Still save token even if decode fails
          window.location.href = "/admin"; // Still redirect to admin
        }
      }
    }
  }, []);
  return children;
}

