/**
 * Sign out user and redirect to the landing page
 * Completely clears session state and redirects to landing page
 */
const signOut = () => {
  try {
    // First, fully clear all session storage
    sessionStorage.clear();

    // Also clear specific keys to ensure they're gone
    sessionStorage.removeItem('idToken');
    sessionStorage.removeItem('shopId');
    sessionStorage.removeItem('userRole');

    // Update state
    setIsAuthenticated(false);
    setUserRole(null);
    setShopId(null);

    // For complete logout, also log out from Cognito
    const domain = process.env.REACT_APP_COGNITO_DOMAIN;
    const clientId = process.env.REACT_APP_COGNITO_CLIENT_ID;
    const baseUrl = window.location.origin;
    const logoutUri = baseUrl + '/';

    // Redirect to Cognito logout, which will then redirect back to our landing page
    window.location.assign(
      `${domain}/logout?client_id=${clientId}&logout_uri=${encodeURIComponent(logoutUri)}`
    );
  } catch (error) {
    console.error('Error during sign out:', error);
    // Fallback to landing page redirect if Cognito logout fails
    sessionStorage.clear();
    window.location.href = '/';
  }
};

