toolUseResult.originalFile:
/* LoginPage.css - Calendar-themed login page styles */

.login-page-background {
  background: linear-gradient(135deg, #1976d2 0%, #64b5f6 100%);
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background-size: cover;
  background-position: center;
  position: relative;
  overflow: hidden;
}

.login-page-background::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background-image: url("data:image/svg+xml,%3Csvg width='60' height='60' viewBox='0 0 60 60' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23ffffff' fill-opacity='0.05' fill-rule='evenodd'%3E%3Cpath d='M36 34v-4h-2v4h-4v2h4v4h2v-4h4v-2h-4zm0-30V0h-2v4h-4v2h4v4h2V6h4V4h-4zM6 34v-4H4v4H0v2h4v4h2v-4h4v-2H6zM6 4V0H4v4H0v2h4v4h2V6h4V4H6z'/%3E%3C/g%3E%3C/svg%3E");
}

.login-container {
  width: 100%;
  max-width: 480px;
  padding: 0;
  position: relative;
  z-index: 1;
}

.login-card {
  background-color: #ffffff;
  border-radius: 16px;
  box-shadow: 0 15px 35px rgba(0, 0, 0, 0.2);
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  position: relative;
  z-index: 10;
  backdrop-filter: blur(5px);
  border: 1px solid rgba(255, 255, 255, 0.1);
}

.login-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.25);
}

.login-header {
  background-color: #1976d2;
  padding: 20px;
  text-align: center;
  position: relative;
  overflow: hidden;
}

.login-header::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-image: url("data:image/svg+xml,%3Csvg width='20' height='20' viewBox='0 0 20 20' xmlns='http://www.w3.org/2000/svg'%3E%3Cg fill='%23ffffff' fill-opacity='0.05' fill-rule='evenodd'%3E%3Ccircle cx='3' cy='3' r='3'/%3E%3Ccircle cx='13' cy='13' r='3'/%3E%3C/g%3E%3C/svg%3E");
}

.login-title {
  color: white;
  margin: 0;
  font-weight: 600;
  font-size: 1.5rem;
  position: relative;
  z-index: 1;
}

.logo-container {
  display: flex;
  justify-content: center;
  margin: 20px 0;
}

.logo-customizable {
  filter: brightness(0) saturate(100%) invert(48%) sepia(79%) saturate(2476%) hue-rotate(86deg) brightness(118%) contrast(119%);
  height: 80px;
  transition: transform 0.3s ease;
}

.logo-customizable:hover {
  transform: scale(1.05);
}

.login-body {
  padding: 30px;
}

.calendar-icon-container {
  display: flex;
  justify-content: center;
  margin-bottom: 20px;
}

.calendar-preview {
  background-color: #f9f9f9;
  border-radius: 8px;
  padding: 15px;
  margin-bottom: 25px;
  box-shadow: inset 0 0 5px rgba(0, 0, 0, 0.05);
}

.calendar-month {
  text-align: center;
  font-weight: 500;
  color: #1976d2;
  margin-bottom: 10px;
  font-size: 1.1rem;
}

.calendar-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 5px;
}

.calendar-day-header {
  text-align: center;
  font-size: 0.7rem;
  font-weight: 500;
  color: #666;
  padding: 5px 0;
}

.calendar-day {
  aspect-ratio: 1/1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  border-radius: 50%;
  color: #333;
}

.calendar-day.today {
  background-color: #1976d2;
  color: white;
  font-weight: 600;
}

.calendar-day.available {
  background-color: #e6f7ee;
  color: #00a86b;
  position: relative;
}

.calendar-day.available::after {
  content: '';
  position: absolute;
  bottom: 3px;
  width: 3px;
  height: 3px;
  background-color: #00a86b;
  border-radius: 50%;
}

.textDescription-customizable {
  text-align: center;
  margin-bottom: 20px;
  color: #555;
  font-size: 1rem;
}

.submitButton-customizable {
  background-color: #1976d2;
  color: white;
  border: none;
  border-radius: 6px;
  padding: 12px;
  font-size: 1rem;
