  text-align: center;
  font-size: 0.7rem;
  font-weight: 500;
  color: #666;
  padding: 5px 0;
}

.calendar-day {
  aspect-ratio: 1/1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  border-radius: 50%;
  color: #333;
}

.calendar-day.today {
  background-color: #1976d2;
  color: white;
  font-weight: 600;
}

.calendar-day.available {
  background-color: #e6f7ee;
  color: #00a86b;
  position: relative;
}

.calendar-day.available::after {
  content: '';
  position: absolute;
  bottom: 3px;
  width: 3px;
  height: 3px;
  background-color: #00a86b;
  border-radius: 50%;
}

.textDescription-customizable {
  text-align: center;
  margin-bottom: 20px;
  color: #555;
  font-size: 1rem;
}

.submitButton-customizable {
  background-color: #1976d2;
  color: white;
  border: none;
  border-radius: 8px;
  padding: 16px;
  font-size: 1.2rem;
  font-weight: 600;
  width: 100%;
  cursor: pointer;
  transition: all 0.3s ease;
  margin-top: 24px;
  margin-bottom: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  text-transform: uppercase;
  letter-spacing: 1px;
  position: relative;
  overflow: hidden;
  box-shadow: 0 4px 12px rgba(25, 118, 210, 0.4);
}

.submitButton-customizable::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: linear-gradient(120deg, rgba(255, 255, 255, 0) 30%, rgba(255, 255, 255, 0.2), rgba(255, 255, 255, 0) 70%);
  transform: translateX(-100%);
  transition: all 0.6s ease;
}

.submitButton-customizable:hover {
  background-color: #0d5ba9;
  box-shadow: 0 8px 20px rgba(13, 91, 169, 0.5);
  transform: translateY(-3px);
}

.submitButton-customizable:hover::before {
  transform: translateX(100%);
}

.submitButton-customizable:active {
  transform: translateY(0);
  box-shadow: 0 3px 10px rgba(13, 91, 169, 0.5);
}

.login-footer {
  text-align: center;
  margin-top: 15px;
}

.legalText-customizable {
  color: #747474;
  font-size: 0.8rem;
}

.errorMessage-customizable {
  background-color: #ffebee;
  color: #d32f2f;
  padding: 10px;
  border-radius: 4px;
  margin-bottom: 20px;
  font-size: 0.9rem;
  border-left: 4px solid #d32f2f;
}

@media (max-width: 600px) {
  .login-container {
    max-width: 90%;
  }

  .login-body {
    padding: 20px;
  }
}

// src/pages/LoginPage.js
import React, { useState, useEffect } from 'react';
import {
  Box,
  Paper,
  Typography,
  Button,
  Container,
  Alert,
  Stack,
  Grid,
} from '@mui/material';
import {jwtDecode} from 'jwt-decode';
import { useConfig } from '../context/ConfigContext';
import AdminPage from './AdminPage';
import CalendarMonthIcon from '@mui/icons-material/CalendarMonth';
import EventAvailableIcon from '@mui/icons-material/EventAvailable';
import '../styles/LoginPage.css';

export default function LoginPage() {
  const [error, setError] = useState('');
  const [ready, setReady] = useState(false);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [currentDate] = useState(new Date());
  const { setUserRole } = useConfig();

  const COGNITO_DOMAIN = process.env.REACT_APP_COGNITO_DOMAIN;
  const COGNITO_CLIENT = process.env.REACT_APP_COGNITO_CLIENT_ID;
  const REDIRECT_URI = process.env.REACT_APP_REDIRECT_URI;
  const SCOPES = 'openid email phone';

  // Generate calendar data for the current month
  const generateCalendarData = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();

    // Get the name of the current month
    const monthName = new Intl.DateTimeFormat('pt-BR', { month: 'long' }).format(
      new Date(year, month, 1)
    );

    // Get the first day of the month
    const firstDay = new Date(year, month, 1).getDay();

    // Get the number of days in the month
    const daysInMonth = new Date(year, month + 1, 0).getDate();

    // Create an array to store the days
    const days = [];

    // Add empty cells for days before the first day of the month
    for (let i = 0; i < firstDay; i++) {
      days.push(null);
    }

    // Add the days of the month
    for (let i = 1; i <= daysInMonth; i++) {
      days.push(i);
    }

    return { monthName, days };
  };

  const { monthName, days } = generateCalendarData();
  const today = currentDate.getDate();

  // Available days (for demo)
  const availableDays = [3, 8, 12, 15, 19, 22, 26, 29];

  // Called once we have a valid id_token
  const finishLogin = idToken => {
    try {
      const payload = jwtDecode(idToken);
      const accountType = payload['custom:accountType'] || 'individual';
      const username = payload['cognito:username'];

      sessionStorage.setItem('idToken', idToken);
      sessionStorage.setItem('shopId', username);
      sessionStorage.setItem('userRole', accountType);

      setUserRole(accountType);
      setIsLoggedIn(true);
      setReady(true);
    } catch (e) {
      setError('Falha ao processar token: ' + e.message);
      setReady(true);
    }
  };

  // On mount: check for stored token or #id_token in hash
  useEffect(() => {
    // 1) Already logged in?
    const stored = sessionStorage.getItem('idToken');
    if (stored) {
      finishLogin(stored);
      return;
    }

    // 2) Look for id_token in URL hash
    const hash = window.location.hash;
    if (hash.includes('id_token=')) {
      const idToken = new URLSearchParams(hash.slice(1)).get('id_token');
      if (idToken) {
        // remove the hash
        window.history.replaceState({}, document.title, window.location.pathname);
        finishLogin(idToken);
        return;
      } else {
        setError('Nenhum id_token encontrado na resposta.');
      }
    }

    // 3) Not logged in yet — show login button
    setReady(true);
  }, []);

  // If we have a token and are "ready," show the app
  if (ready && isLoggedIn) {
    return <AdminPage />;
  }

  // Otherwise, show the Entrar button for implicit flow
  const handleHostedUi = () => {
    const params = new URLSearchParams({
      response_type: 'token',
      client_id: COGNITO_CLIENT,
      redirect_uri: REDIRECT_URI,
      scope: SCOPES,
      screen_hint: 'signup', // optional: jump straight to the sign-up form
      lang: 'pt-BR', // Portuguese localization
    });
    window.location.assign(
      `${COGNITO_DOMAIN}/oauth2/authorize?${params.toString()}`
    );
  };

  // Days of the week for the calendar
  const daysOfWeek = ['D', 'S', 'T', 'Q', 'Q', 'S', 'S'];

  return (
    <Box className="login-page-background">
      <Container className="login-container">
        <Paper elevation={5} className="login-card">
          {/* Header */}
          <Box className="login-header">
            <Typography variant="h5" className="login-title">
              Sistema de Agendamentos
            </Typography>
          </Box>

          {/* Logo */}
          <Box className="logo-container">
            <Box
              component="img"
              src="/images/logo.png"
              alt="Aisol Logo"
              className="logo-customizable"
            />
          </Box>

          <Box className="login-body">
            {/* Calendar Icon */}
            <Box className="calendar-icon-container">
              <CalendarMonthIcon 
                color="primary" 
                sx={{ fontSize: 60, opacity: 0.9 }} 
              />
            </Box>

            <Typography 
              variant="h4" 
              align="center" 
              sx={{ 
                fontWeight: 600, 
                color: '#333',
                mb: 2
              }}
            >
              Calendário de Agendamentos
            </Typography>

            {/* Calendar Preview */}
            <Box className="calendar-preview">
              <Typography variant="h6" className="calendar-month">
                {monthName.charAt(0).toUpperCase() + monthName.slice(1)}
              </Typography>

              <Grid container className="calendar-grid">
                {/* Day headers */}
                {daysOfWeek.map((day, index) => (
                  <Box key={index} className="calendar-day-header">
                    {day}
                  </Box>
                ))}

                {/* Calendar days */}
                {days.map((day, index) => (
                  <Box 
                    key={index} 
                    className={`calendar-day ${day === today ? 'today' : ''} ${availableDays.includes(day) ? 'available' : ''}`}
                  >
                    {day}
                  </Box>
                ))}
              </Grid>
            </Box>

            {/* Description */}
            <Typography className="textDescription-customizable">
              Acesse nossa plataforma para gerenciar seus agendamentos de forma simples e eficiente.
            </Typography>

            {/* Error message */}
            {error && <Alert severity="error" className="errorMessage-customizable">{error}</Alert>}

            {/* Login button */}
            <Button
              onClick={handleHostedUi}
              variant="contained"
              size="large"
              fullWidth
              className="submitButton-customizable"
              startIcon={<EventAvailableIcon />}
            >
              Comece Agora
            </Button>

            {/* Helper text */}
            <Box className="login-footer">
              <Typography variant="body2" className="legalText-customizable">
                Não tem conta? Faça seu cadastro na próxima tela.
              </Typography>
            </Box>
          </Box>
        </Paper>

        {/* Footer */}
        <Box 
          sx={{ 
            mt: 4, 
            textAlign: 'center',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            gap: 1
          }}
        >
          <Box
            component="img"
            src="/images/logo.png"
            alt="Aisol Logo"
            sx={{
              height: '24px',
              filter: 'brightness(0) saturate(100%) invert(48%) sepia(79%) saturate(2476%) hue-rotate(86deg) brightness(118%) contrast(119%)' // Green tint
            }}
          />
          <Typography variant="body2" className="legalText-customizable">
            Powered by Aisol© 2025
          </Typography>
        </Box>
      </Container>
    </Box>
  );
}

