              Agendamentos Online
            </Typography>
          </Box>

          {/* Logo */}
          <Box className="logo-container">
            <Box
              component="img"
              src="/images/logo.png"
              alt="Aisol Logo"
              className="logo-customizable"
            />
          </Box>

          <Box className="login-body">
            {/* Hero Section with Icon and Title */}
            <Box sx={{ 
              display: 'flex',
              flexDirection: 'column',
              alignItems: 'center',
              mb: 3,
              position: 'relative'
            }}>
              <Box 
                sx={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  position: 'relative',
                  zIndex: 5
                }}
              >
                <CalendarMonthIcon 
                  color="primary" 
                  sx={{ 
                    fontSize: 70, 
                    filter: 'drop-shadow(0 4px 10px rgba(25, 118, 210, 0.3))',
                    animation: 'pulse 2s infinite ease-in-out',
                    mr: 2
                  }} 
                />
                <Box>
                  <Typography 
                    variant="h3" 
                    align="left" 
                    sx={{ 
                      fontWeight: 800, 
                      color: '#1976d2',
                      lineHeight: 1.1,
                      letterSpacing: '-0.5px',
                      fontSize: { xs: '2.2rem', sm: '2.5rem' }
                    }}
                  >
                    Calendário
                  </Typography>
                  <Typography 
                    variant="h5" 
                    align="left" 
                    sx={{ 
                      fontWeight: 400, 
                      color: '#666',
                      mt: 0.5
                    }}
                  >
                    de Agendamentos
                  </Typography>
                </Box>
              </Box>
            </Box>

            {/* Calendar Preview - Simplified */}
            <Box sx={{ 
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 3,
              gap: 2,
              flexWrap: 'wrap'
            }}>
              {/* Available Days Indicator */}
              <Box sx={{ 
