          <Box className="login-header">
            <Typography variant="h5" className="login-title">
              Agendamentos Online
            </Typography>
          </Box>

          {/* Logo */}
          <Box className="logo-container">
            <Box
              component="img"
              src="/images/logo.png"
              alt="Aisol Logo"
              className="logo-customizable"
            />
          </Box>

          <Box className="login-body" sx={{ pt: 1, pb: 2 }}>
            {/* Hero Section with Icon and Title - Compact */}
            <Box sx={{ 
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              mb: 2,
              position: 'relative'
            }}>
              <CalendarMonthIcon 
                color="primary" 
                sx={{ 
                  fontSize: 48, 
                  filter: 'drop-shadow(0 4px 10px rgba(25, 118, 210, 0.3))',
                  animation: 'pulse 2s infinite ease-in-out',
                  mr: 1.5
                }} 
              />
              <Box>
                <Typography 
                  variant="h4" 
                  align="left" 
                  sx={{ 
                    fontWeight: 800, 
                    color: '#1976d2',
                    lineHeight: 1,
                    letterSpacing: '-0.5px',
                    fontSize: { xs: '1.8rem', sm: '2rem' }
                  }}
                >
                  Agendamentos
                </Typography>
                <Typography 
                  variant="subtitle1" 
                  align="left" 
                  sx={{ 
                    fontWeight: 400, 
                    color: '#666',
                    fontSize: '0.9rem'
                  }}
                >
                  simples e eficientes
                </Typography>
              </Box>
            </Box>

            {/* Calendar Preview - Simplified */}
            <Box sx={{ 
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
