                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  borderRadius: '50%',
                  border: '2px solid rgba(0, 168, 107, 0.2)'
                }}>
                  {today}
                </Box>
                <Typography variant="body2" sx={{ color: '#555' }}>
