                  }}
                >
                  Agendamentos
                </Typography>
                <Typography 
                  variant="subtitle1" 
                  align="left" 
                  sx={{ 
                    fontWeight: 400, 
                    color: '#666',
                    fontSize: '0.9rem'
                  }}
                >
                  simples e eficientes
                </Typography>
              </Box>
            </Box>

            {/* Calendar Preview - Simplified */}
            <Box sx={{ 
              display: 'flex',
